typedef void (*Callback)(int, const char *);

void register_callback(Callback cb, int type_pattern, ...) {
    va_list args;
    va_start(args, type_pattern);
    if (type_pattern == 1) {
        int extra_int = va_arg(args, int);
        // process based on pattern 1
    } else if (type_pattern == 2) {
        const char *extra_str = va_arg(args, const char *);
        // process based on pattern 2
    }
    va_end(args);
    // Store or invoke callback with context-specific arguments
}
